const translationTextSource=new WeakMap(),translationAttrSource=new WeakMap();
function translateDynamic(){
  const dict=lang==='en'?enDict:Object.fromEntries(Object.entries(enDict).map(([a,b])=>[b,a]));
  const keys=Object.keys(dict).filter(Boolean).sort((a,b)=>b.length-a.length);
  // Replace from the original string in one pass. Never translate already-translated output.
  const escapeRegex=value=>[...value].map(ch=>'.*+?^${}()|[]\\'.includes(ch)?'\\'+ch:ch).join('');
  const pattern=keys.length?new RegExp('(^|[^\\p{L}\\p{N}])('+keys.map(escapeRegex).join('|')+')(?=$|[^\\p{L}\\p{N}])','gu'):null;
  const convert=source=>pattern?source.replace(pattern,(whole,lead,key)=>lead+dict[key]):source;
  const walk=node=>{
    if(node.nodeType===Node.TEXT_NODE){
      if(!translationTextSource.has(node))translationTextSource.set(node,node.nodeValue);
      const original=translationTextSource.get(node);
      if(original.trim())node.nodeValue=convert(original);
    }else if(node.nodeType===Node.ELEMENT_NODE){
      if(node.hasAttribute('data-bn'))return;
      ['placeholder','title'].forEach(attr=>{
        if(!node.hasAttribute(attr))return;
        let saved=translationAttrSource.get(node);if(!saved){saved={};translationAttrSource.set(node,saved)}
        if(saved[attr]===undefined)saved[attr]=node.getAttribute(attr);
        node.setAttribute(attr,convert(saved[attr]));
      });
      [...node.childNodes].forEach(walk);
    }
  };
  document.querySelectorAll('.app,.login-screen').forEach(walk);
}
// Translation is applied explicitly after rendering. Avoid a document-wide MutationObserver
// so text updates cannot interfere with login inputs or focus while typing.
function setLang(){document.querySelectorAll('[data-bn]').forEach(el=>{const value=el.dataset[lang]||el.dataset.bn;if(el.matches('label')&&el.querySelector('input,select,textarea')){let textNode=[...el.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim());if(textNode)textNode.textContent=value+' ';else{const span=document.createElement('span');span.textContent=value;el.insertBefore(span,el.firstChild)}}else if(el.children.length===0){el.textContent=value}else{const textNode=[...el.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim());if(textNode)textNode.textContent=value}});$('langBtn').textContent=lang==='bn'?'English':'বাংলা';$('loginLang').textContent=lang==='bn'?'English':'বাংলা';$('pageTitle').textContent=lang==='en'?(labels[page]||page):({dashboard:'ড্যাশবোর্ড',admission:'ভর্তি আবেদন',routine:'ক্লাস রুটিন',students:'শিক্ষার্থী',teachers:'শিক্ষক',classes:'ক্লাস',subjects:'সাবজেক্ট',attendance:'উপস্থিতি',exams:'পরীক্ষা',results:'ফলাফল',fees:'বেতন ও পেমেন্ট',notices:'নোটিশ',reports:'রিপোর্ট',settings:'সেটিংস',idcard:'আইডি কার্ড'}[page]||page);document.documentElement.lang=lang;translateDynamic()}
function switchPage(p){page=p;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+p));document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('pageTitle').textContent=labels[p]||p;location.hash=p;$('sidebar').classList.remove('open');renderPage(p)}
async function load(name){const s=await col(name).get();cache[name]=s.docs.map(d=>({id:d.id,...d.data()}));return cache[name]}
function dateSort(a,b){return String(b.createdAt?.toDate?.()||b.date||'').localeCompare(String(a.createdAt?.toDate?.()||a.date||''))}
function table(rows,heads,empty='কোনো তথ্য পাওয়া যায়নি'){return `<div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td class="empty" colspan="${heads.length}">${empty}</td></tr>`}</tbody></table></div></div>`}
function actionBtns(id){return `<div class="actions"><button data-edit="${esc(id)}">সম্পাদনা</button><button class="danger" data-del="${esc(id)}">মুছুন</button></div>`}
function inputFor(entity,f){const [key,label,type='text',required]=f;let val=entity?.[key]??(key==='fatherName'?(entity?.fatherNameEn||entity?.fatherName||''):key==='motherName'?(entity?.motherNameEn||entity?.motherName||''):'');let html='';const opts=(arr,placeholder)=>`<select name="${key}" ${required?'required':''}><option value="">${placeholder}</option>${arr.map(([v,t])=>`<option value="${esc(v)}" ${String(val)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>`;if(type==='blood')html=opts(['A+','A-','B+','B-','O+','O-','AB+','AB-'].map(x=>[x,x]),'Select Blood Group');else if(type==='religion')html=opts(['Islam','Hinduism','Buddhism','Christianity','Other'].map(x=>[x,x]),'Select Religion');else if(type==='nationality')html=opts(['Bangladeshi','Other'].map(x=>[x,x]),'Select Nationality');else if(type==='relation')html=opts(['Father','Mother','Brother','Sister','Grandfather','Grandmother','Legal Guardian','Other'].map(x=>[x,x]),'Select Relationship');else if(type==='marital')html=opts(['Unmarried','Married','Other'].map(x=>[x,x]),'Select Marital Status');else if(type==='year'){html=`<input name="${key}" type="number" min="1900" step="1" value="${esc(val||new Date().getFullYear())}" placeholder="Enter academic year" ${required?'required':''}>`}else if(type==='section')html=opts(['A','B','C','D','N/A'].map(x=>[x,x]),'Select Section');else if(type==='grade')html=`<select name="${key}" required><option value="">Select Class</option>${gradeList.map(x=>`<option ${val===x?'selected':''}>${x}</option>`).join('')}</select>`;else if(type==='select')html=`<select name="${key}" ${required?'required':''}><option value="">Select Class</option>${[...new Set(cache.classes.map(c=>c.className))].map(x=>`<option value="${esc(x)}" ${val===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;else if(type==='group')html=`<select name="${key}" id="formGroup"><option value="">No Group / Select</option>${['Humanities','Science','Commerce'].map(x=>`<option ${val===x?'selected':''}>${x}</option>`).join('')}</select>`;else if(type==='classSelect')html=`<select name="${key}" required><option value="">Select Class</option>${cache.classes.map(c=>`<option value="${esc(c.id)}" ${val===c.id?'selected':''}>${esc([c.className,c.group].filter(Boolean).join(' · '))}</option>`).join('')}</select>`;else if(type==='teacher')html=`<select name="${key}" ${required?'required':''}><option value="">Select Teacher</option>${cache.teachers.map(t=>`<option value="${esc(t.id)}" ${val===t.id?'selected':''}>${esc(t.nameEn||'')} · ${esc(t.teacherId||'')}</option>`).join('')}</select>`;else if(type==='gender')html=`<select name="${key}"><option value="">Select</option><option value="male" ${val==='male'?'selected':''}>Male</option><option value="female" ${val==='female'?'selected':''}>Female</option><option value="other" ${val==='other'?'selected':''}>Other</option></select>`;else if(type==='status')html=`<select name="${key}"><option value="active" ${val!=='inactive'?'selected':''}>Active</option><option value="inactive" ${val==='inactive'?'selected':''}>Inactive</option></select>`;else if(type==='textarea')html=`<textarea name="${key}" rows="2" placeholder="Enter details">${esc(Array.isArray(val)?val.join(', '):val)}</textarea>`;else html=`<input name="${key}" type="${type}" value="${esc(val)}" ${required?'required':''}>`;return `<label>${label}${required?' *':''}${html}</label>`}
function classSortValue(v){const map={'প্লে':0,'নার্সারি':1,'কেজি':2,'Play':0,'Nursery':1,'KG':2};if(map[v]!=null)return map[v];const n=parseInt(String(v).replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d)),10);return Number.isFinite(n)?n+3:999}
function mountCrud(name){const mount=$(name+'Mount'),fields=cols[name];let query='',classFilter='all',statusFilter='all';function render(){let source=[...cache[name]];if(name==='students')source.sort((a,b)=>(classSortValue(a.className)-classSortValue(b.className))||String(a.group||'').localeCompare(String(b.group||''),'bn')||((Number(a.roll)||999999)-(Number(b.roll)||999999))||String(a.nameBn||'').localeCompare(String(b.nameBn||''),'bn'));if(name==='classes')source.sort((a,b)=>classSortValue(a.className)-classSortValue(b.className)||String(a.group||'').localeCompare(String(b.group||''),'bn'));const list=source.filter(x=>{const text=JSON.stringify(x).toLowerCase();const c=name==='students'?x.className:name==='subjects'?(cache.classes.find(z=>z.id===x.classId)?.className||x.className):'';return text.includes(query)&&(classFilter==='all'||c===classFilter)&&(statusFilter==='all'||(x.status||'active')===statusFilter)});const heads=name==='students'?['ছবি','ID','নাম','Class','শাখা/বিভাগ','Roll','অভিভাবক ফোন','Status','কাজ']:name==='teachers'?['ছবি','ID','নাম','পদবি','বিষয়','মোবাইল','Status','কাজ']:name==='classes'?['Class','রুম নম্বর','Group','কাজ']:['সাবজেক্টের নাম','সাবজেক্ট কোড','ক্লাস','সাবজেক্ট টিচার','কাজ'];const rows=list.map(x=>{let cells=name==='students'?[`<img class="person-thumb" src="${esc(x.photoURL||'')}" alt="" onerror="this.style.display='none'">`,x.studentId,x.nameEn,x.className,(x.section||'—')+(x.group?' / '+x.group:''),x.roll,x.guardianPhone,x.status]:name==='teachers'?[`<img class="person-thumb" src="${esc(x.photoURL||'')}" alt="" onerror="this.style.display='none'">`,x.teacherId,x.nameEn,x.designation,x.subject,x.phone,x.status]:name==='classes'?[x.className,x.roomNumber||'—',x.group||'—']:[x.subjectName,x.subjectCode,(cache.classes.find(c=>c.id===x.classId)?.className||x.className||'—'),(cache.teachers.find(t=>t.id===x.teacherId)?.nameEn||'—')];return `<tr>${cells.map((c,i)=>`<td>${(name==='students'&&i===0)||(name==='teachers'&&i===0)?c:esc(c||'—')}</td>`).join('')}<td>${actionBtns(x.id)}</td></tr>`});const classes=[...new Set(cache.classes.map(c=>c.className).filter(Boolean))].sort((a,b)=>classSortValue(a)-classSortValue(b));mount.innerHTML=`<div class="toolbar"><input id="${name}Search" placeholder="নাম, আইডি, কোড বা তথ্য দিয়ে খুঁজুন..." value="${esc(query)}"><select id="${name}ClassFilter"><option value="all">সব শ্রেণি</option>${['students','subjects'].includes(name)?classes.map(c=>`<option ${classFilter===c?'selected':''}>${esc(c)}</option>`).join(''):''}</select>${['students','teachers'].includes(name)?`<select id="${name}StatusFilter"><option value="all">সব অবস্থা</option><option value="active" ${statusFilter==='active'?'selected':''}>সক্রিয়</option><option value="inactive" ${statusFilter==='inactive'?'selected':''}>নিষ্ক্রিয়</option></select>`:''}<span class="badge">${list.length} / ${cache[name].length} রেকর্ড</span></div><div id="${name}Form"></div>${table(rows,heads)}`;mount.querySelector('#'+name+'Search').addEventListener('input',e=>{query=e.target.value.toLowerCase();render()});mount.querySelector('#'+name+'ClassFilter')?.addEventListener('change',e=>{classFilter=e.target.value;render()});mount.querySelector('#'+name+'StatusFilter')?.addEventListener('change',e=>{statusFilter=e.target.value;render()});mount.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>form(b.dataset.edit));mount.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>remove(name,b.dataset.del));}

async function form(id=''){const item=cache[name].find(x=>x.id===id)||{},fieldsHtml=fields.map(f=>inputFor(item,f)).join('');mount.querySelector('#'+name+'Form').innerHTML=`<form class="form-card" id="${name}Editor"><h3>${id?'Edit Information':'New '+(name==='students'?'Student':name==='teachers'?'শিক্ষক':name==='classes'?'ক্লাস':'সাবজেক্ট')}</h3><div class="form-grid">${fieldsHtml}</div><div class="form-actions"><button class="primary" type="submit">${id?'আপডেট করুন':'Save'}</button><button class="secondary" type="button" id="cancelEditor">বাতিল</button></div><p class="error" id="editorError"></p></form>`;
const formEl=mount.querySelector('#'+name+'Editor');formEl.querySelector('[name="className"]')?.addEventListener('change',e=>{const g=formEl.querySelector('[name="group"]');if(g){g.disabled=!['৯','১০','9','10','নবম','দশম'].includes(e.target.value);if(g.disabled)g.value=''}});const gradeSelect=formEl.querySelector('[name="className"]');if(gradeSelect){const g=formEl.querySelector('[name="group"]');if(g){g.disabled=!['৯','১০','9','10','নবম','দশম'].includes(gradeSelect.value);if(g.disabled)g.value=''}}formEl.querySelector('#cancelEditor').onclick=()=>{mount.querySelector('#'+name+'Form').innerHTML=''};formEl.onsubmit=async e=>{e.preventDefault();const fd=new FormData(formEl),data={};fields.forEach(f=>{let v=fd.get(f[0]);if(f[0]==='subjects')v=String(v||'').split(',').map(x=>x.trim()).filter(Boolean);if(v!==null)data[f[0]]=String(v).trim()});if(['students','teachers'].includes(name)&&data.photoURL&&!/^https?:\/\//i.test(data.photoURL)){formEl.querySelector('#editorError').textContent='Enter a valid https:// image URL.';return}if(name==='classes'){data.group=['৯','১০','9','10','নবম','দশম'].includes(data.className)?(data.group||'') : '';const dup=cache.classes.find(c=>c.id!==id&&c.className===data.className&&(c.group||'')===(data.group||''));if(dup){formEl.querySelector('#editorError').textContent='This class and group already exist.';return}}if(name==='subjects'){const c=cache.classes.find(x=>x.id===data.classId),t=cache.teachers.find(x=>x.id===data.teacherId);if(!c){formEl.querySelector('#editorError').textContent='Create a class first.';return}data.className=c.className;data.group=c.group||'';data.teacherName=t?.nameEn||'';const dup=cache.subjects.find(x=>x.id!==id&&x.subjectCode===data.subjectCode&&x.classId===data.classId);if(dup){formEl.querySelector('#editorError').textContent='This subject code already exists in this class.';return}}try{if(name==='students'&&!id)data.studentId=await nextId('student','ST',4);if(name==='teachers'&&!id)data.teacherId=await nextId('teacher','TC',3);data.updatedAt=firebase.firestore.FieldValue.serverTimestamp();if(id)await col(name).doc(id).update(data);else{data.createdAt=firebase.firestore.FieldValue.serverTimestamp();await col(name).add(data)}toast(name==='students'&&!id?'শিক্ষার্থী সংরক্ষিত · ID: '+data.studentId:name==='teachers'&&!id?'শিক্ষক সংরক্ষিত · ID: '+data.teacherId:'Information saved successfully');await load(name);render();if(name==='students'||name==='teachers'||name==='classes')dashboard();if(name==='subjects')await load('subjects');}catch(err){formEl.querySelector('#editorError').textContent=err.message}};
}
openCrudForm[name]=form;render();}
async function remove(name,id){if(!confirm('এই রেকর্ডটি স্থায়ীভাবে মুছে ফেলবেন?'))return;try{await col(name).doc(id).delete();await load(name);mountCrud(name);toast('রেকর্ড মুছে ফেলা হয়েছে');dashboard()}catch(e){msgError(e)}}
function renderClasses(){mountCrud('classes')}
async function subjectsPage(){await Promise.all([load('subjects'),load('classes'),load('teachers')]);let migrated=0;for(const c of cache.classes){const legacy=Array.isArray(c.subjects)?c.subjects:[];for(let i=0;i<legacy.length;i++){const subjectName=String(legacy[i]||'').trim();if(!subjectName||cache.subjects.some(s=>s.classId===c.id&&String(s.subjectName||'').toLowerCase()===subjectName.toLowerCase()))continue;const subjectCode=`LEG-${String(c.id).slice(0,5)}-${i+1}`;await col('subjects').add({subjectName,subjectCode,classId:c.id,className:c.className,group:c.group||'',teacherId:'',teacherName:'',legacyImported:true,createdAt:firebase.firestore.FieldValue.serverTimestamp()});migrated++}}if(migrated){await load('subjects');toast(`${migrated}টি পুরোনো সাবজেক্ট আলাদা তালিকায় আনা হয়েছে; কোড/শিক্ষক যাচাই করুন।`)}mountCrud('subjects')}
function classOptions(){return cache.classes.map(c=>({value:c.id,label:[c.className,c.group].filter(Boolean).join(' · ')}))}

function attachTableFilters(mountId, tableSelector='tbody'){const root=$(mountId);if(!root)return;const tbl=root.querySelector(tableSelector);if(!tbl)return;const rows=[...tbl.querySelectorAll('tr')];const bar=document.createElement('div');bar.className='toolbar table-filter';bar.innerHTML='<input type="search" placeholder="তালিকার তথ্য দিয়ে খুঁজুন..." aria-label="Search records">';root.insertBefore(bar,root.firstChild);bar.querySelector('input').addEventListener('input',e=>{const q=e.target.value.toLowerCase();rows.forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q))});}
async function attendancePage(){
  const m=$('attendanceMount');
  await Promise.all([load('students'),load('classes'),load('attendance')]);
  const classOpts=classOptions();
  m.innerHTML=`<section class="attendance-shell">
    <div class="attendance-toolbar">
      <label><span>তারিখ / Date</span><input type="date" id="attDate" value="${dateNow()}"></label>
      <label><span>শ্রেণি / Class</span><select id="attClass"><option value="">Select Class</option>${classOpts.map(o=>`<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('')}</select></label>
      <label><span>শাখা / Section</span><select id="attSection" disabled><option value="all">সকল শাখা</option></select></label>
      <button class="primary" id="loadAtt" type="button">শিক্ষার্থী দেখুন</button>
    </div>
    <div class="attendance-summary" id="attSummary"><span>শিক্ষার্থী নির্বাচন করুন</span><span>উপস্থিতি সংরক্ষণের আগে তালিকা যাচাই করুন</span></div>
    <div id="attList"><div class="attendance-empty">তারিখ ও শ্রেণি নির্বাচন করে শিক্ষার্থীদের তালিকা লোড করুন।</div></div>
  </section>`;
  const classEl=$('attClass'),sectionEl=$('attSection');
  function fillSections(){
    const c=cache.classes.find(x=>x.id===classEl.value);
    const sections=[...new Set(cache.students.filter(x=>c&&x.className===c.className&&(!c.group||(x.group||'')===c.group)).map(x=>String(x.section||'').trim()).filter(Boolean))].sort();
    sectionEl.innerHTML='<option value="all">সকল শাখা</option>'+sections.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
    sectionEl.disabled=!c||sections.length===0;
  }
  classEl.addEventListener('change',fillSections);
  $('loadAtt').onclick=async()=>{
    const cid=classEl.value,date=$('attDate').value,c=cache.classes.find(x=>x.id===cid),section=sectionEl.value;
    if(!cid||!date){toast('তারিখ ও শ্রেণি নির্বাচন করুন');return;}
    const students=cache.students.filter(st=>st.className===c.className&&(!c.group||(st.group||'')===c.group)&&(section==='all'||(st.section||'')===section)&&st.status!=='inactive').sort((a,b)=>String(a.roll||'').localeCompare(String(b.roll||''),undefined,{numeric:true}));
    let old={};
    try{const snap=await col('attendance').where('date','==',date).where('classId','==',cid).get();snap.forEach(d=>old[d.data().studentId]=d.data());}
    catch(e){try{const snap=await col('attendance').get();snap.forEach(d=>{const x=d.data();if(x.date===date&&x.classId===cid)old[x.studentId]=x;});}catch(err){msgError(err);return;}}
    const summary=$('attSummary');
    summary.innerHTML=`<span><b>${students.length}</b> জন শিক্ষার্থী</span><span>${esc(c.className)}${c.group?' · '+esc(c.group):''}${section!=='all'?' · '+esc(section):''} · ${esc(date)}</span>`;
    $('attList').innerHTML=students.length?`<div class="attendance-list-head"><span>শিক্ষার্থী</span><span>উপস্থিতির অবস্থা</span></div>`+students.map((st,i)=>{const rec=old[st.id];return `<div class="attendance-item"><div class="attendance-person"><span class="attendance-number">${i+1}</span><div><b>${esc(st.nameBn||st.nameEn||'—')}</b><small>${esc(st.studentId||'')} · Roll ${esc(st.roll||'—')}</small></div></div><select class="attendance-status status-${esc(rec?.status||'present')}" data-student="${esc(st.id)}"><option value="present" ${!rec||rec.status==='present'?'selected':''}>উপস্থিত</option><option value="absent" ${rec?.status==='absent'?'selected':''}>অনুপস্থিত</option><option value="late" ${rec?.status==='late'?'selected':''}>বিলম্বে</option><option value="leave" ${rec?.status==='leave'?'selected':''}>ছুটি</option></select></div>`}).join('')+`<div class="attendance-footer"><span id="attCount">উপস্থিতির তথ্য যাচাই করে সংরক্ষণ করুন</span><button class="primary" id="saveAttendance" type="button">উপস্থিতি সংরক্ষণ</button></div>`:`<div class="attendance-empty">এই শ্রেণি/শাখায় কোনো সক্রিয় শিক্ষার্থী পাওয়া যায়নি। শিক্ষার্থীর প্রোফাইলে শ্রেণি, বিভাগ ও শাখা যাচাই করুন।</div>`;
    const list=$('attList');
    const updateCount=()=>{const sels=[...list.querySelectorAll('[data-student]')],counts={present:0,absent:0,late:0,leave:0};sels.forEach(x=>counts[x.value]++);$('attCount').textContent=`উপস্থিত ${counts.present} · অনুপস্থিত ${counts.absent} · বিলম্বে ${counts.late} · ছুটি ${counts.leave}`;};
    list.querySelectorAll('[data-student]').forEach(sel=>{sel.addEventListener('change',()=>{sel.className='attendance-status status-'+sel.value;updateCount();});});updateCount();
    $('saveAttendance')?.addEventListener('click',async()=>{
      const btn=$('saveAttendance');btn.disabled=true;btn.textContent='সংরক্ষণ হচ্ছে…';
      try{const batch=db.batch();list.querySelectorAll('[data-student]').forEach(sel=>{const st=students.find(x=>x.id===sel.dataset.student);if(!st)return;const ref=col('attendance').doc(`${date}_${cid}_${st.id}`);batch.set(ref,{date,classId:cid,className:c.className,section:st.section||'',group:c.group||st.group||'',studentId:st.id,studentCode:st.studentId||'',studentName:st.nameBn||st.nameEn||'',roll:st.roll||'',status:sel.value,updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});});await batch.commit();await load('attendance');toast('উপস্থিতি সফলভাবে সংরক্ষিত হয়েছে');dashboard();btn.textContent='সংরক্ষিত হয়েছে';}
      catch(e){msgError(e);btn.disabled=false;btn.textContent='আবার চেষ্টা করুন';}
    });
  };
}
