  const inputs=[...box.querySelectorAll('[data-mark-index]')];const updateTotal=()=>{$('marksLiveTotal').textContent='মোট প্রাপ্ত নম্বর: '+inputs.reduce((a,x)=>a+(Number(x.value)||0),0)};inputs.forEach(x=>x.addEventListener('input',updateTotal));updateTotal();
